// Builds src/features/docs/docs.generated.ts from the markdown pages in src/features/docs/content.
// Each page starts with a front-matter block:
//
//   ---
//   title: Quickstart
//   description: One line for search results and link previews.
//   section: getting-started
//   order: 2
//   ---
//
// The page's URL is /docs/<file name without .md>. Run `npm run docs:build -w @skirm/web` after
// editing a page; docs.test.ts fails when the generated file is out of date.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const contentDir = path.join(here, '..', 'src', 'features', 'docs', 'content');
const outFile = path.join(here, '..', 'src', 'features', 'docs', 'docs.generated.ts');

export function parsePage(file, raw) {
  const text = raw.replace(/\r\n/g, '\n');
  const match = /^---\n([\s\S]*?)\n---\n/.exec(text);
  if (!match) throw new Error(`${file}: missing front matter`);
  const meta = {};
  for (const line of match[1].split('\n')) {
    const i = line.indexOf(':');
    if (i > 0) meta[line.slice(0, i).trim()] = line.slice(i + 1).trim();
  }
  for (const key of ['title', 'description', 'section', 'order']) {
    if (!meta[key]) throw new Error(`${file}: front matter needs "${key}"`);
  }
  return {
    slug: path.basename(file, '.md'),
    title: meta.title,
    description: meta.description,
    section: meta.section,
    order: Number(meta.order),
    body: text.slice(match[0].length).trim(),
  };
}

export function buildDocs() {
  const pages = fs
    .readdirSync(contentDir)
    .filter((f) => f.endsWith('.md'))
    .sort()
    .map((f) => parsePage(f, fs.readFileSync(path.join(contentDir, f), 'utf8')));
  return (
    '// Generated by scripts/build-docs.mjs from src/features/docs/content/*.md. Do not edit by hand.\n' +
    "import type { DocPage } from './types';\n\n" +
    `export const DOC_PAGES: DocPage[] = ${JSON.stringify(pages, null, 2)};\n`
  );
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  const out = buildDocs();
  if (process.argv.includes('--check')) {
    const current = fs.existsSync(outFile) ? fs.readFileSync(outFile, 'utf8').replace(/\r\n/g, '\n') : '';
    if (current !== out) {
      console.error('docs.generated.ts is out of date: run npm run docs:build -w @skirm/web');
      process.exit(1);
    }
  } else {
    fs.writeFileSync(outFile, out);
    console.log(`wrote ${path.relative(process.cwd(), outFile)}`);
  }
}
